#!/usr/bin/env bash
# Installs the git hooks of this repository (currently only pre-commit, which updates copyright headers).
# Works with bash on Linux and macOS, and with git-bash on Windows. Usage: tools/install-hooks.sh [--force|--uninstall]
# AUTOGENERATED COPYRIGHT HEADER START
# Copyright (C) 2026 Claude <noreply@anthropic.com>
# AUTOGENERATED COPYRIGHT HEADER END
set -eu

top="$(git rev-parse --show-toplevel)"
hook="$(cd "$top" && git rev-parse --git-path hooks)/pre-commit"
case "$hook" in /*) ;; *) hook="$top/$hook" ;; esac
marker="BlitzLLVM pre-commit hook"

if [ "${1:-}" = "--uninstall" ]; then
	if [ -f "$hook" ] && grep -q "$marker" "$hook"; then rm -f "$hook"; echo "Removed $hook."; else echo "Nothing to remove."; fi
	exit 0
fi

if [ -e "$hook" ] && ! grep -q "$marker" "$hook" && [ "${1:-}" != "--force" ]; then
	echo "A different pre-commit hook already exists at '$hook'. Use --force to replace it." >&2
	exit 1
fi

mkdir -p "$(dirname "$hook")"
cat > "$hook" <<'STUB'
#!/bin/sh
# BlitzLLVM pre-commit hook, installed by tools/install-hooks.sh.
exec bash "$(git rev-parse --show-toplevel)/tools/pre-commit.sh" "$@"
STUB
chmod +x "$hook" "$top/tools/pre-commit.sh"
echo "Installed $hook."
